int mystery( unsigned bits ) 
{ 
   unsigned i;  
   unsigned mask = 1 << 31;  
   unsigned total = 0;  

   for ( i = 1; i <= 32; i++, bits <<= 1 )  
  {  
if ( ( bits & mask ) == mask )  

       total++; 
  } 
  return !( total % 2 ) ? 1 : 0; 
 } 


